import{_ as a}from"./chunks/maintile_even.CcZ74T4j.js";import{_ as n,o as p,a as l,b as c}from"./app.BGziXukh.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/operator_practice"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"矢量编程（C API）","link":"/guide/operator_practice/simd_operator_impl/vector_programming_c_api/vector_programming_c_api"},{"text":"多核Tiling切分","link":"/guide/operator_practice/simd_operator_impl/vector_programming_c_api/multi_core_tiling/multi_core_tiling"},{"text":"主块均分","link":"/guide/operator_practice/simd_operator_impl/vector_programming_c_api/multi_core_tiling/main_block_even_split"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/vector_programming_c_api/multi_core_tiling/main_block_even_split.md","filePath":"guide/operator_practice/simd_operator_impl/vector_programming_c_api/multi_core_tiling/main_block_even_split.md","outlineHeaders":[{"level":2,"title":"Tiling实现","slug":"Tiling实现","link":"#Tiling实现"},{"level":2,"title":"算子类实现","slug":"算子类实现","link":"#算子类实现"},{"level":2,"title":"Reg矢量函数实现","slug":"Reg矢量函数实现","link":"#Reg矢量函数实现"}],"lastUpdated":1795433433000}'),e={name:"guide/operator_practice/simd_operator_impl/vector_programming_c_api/multi_core_tiling/main_block_even_split.md"};function t(o,s,i,w,d,_){return p(),l("div",null,[...s[0]||(s[0]=[c('<div><article class="markdown-body"><h1>主块均分</h1><p>长度为<code>totalLength</code>的输入数据可以按参与计算的核数和主块长度<code>mainTileLength</code>均匀切分，主块均分后无剩余数据。各核处理的数据量相同，每个核处理<code>tileNum</code>个主块，核内只包含主块。</p><p><strong>图1</strong> 数据切分示意图</p><p><img src="'+a+`" alt="数据切分示意图" title="数据切分示意图"></p><p>本场景原基础API样例的完整代码请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/02_tiling_selector/vector_tiling_strategy/README.md#scenario0-main-tile-only">场景0：主块均分</a>。样例中固定使用8个核，主块长度<code>mainTileLength</code>为3200个<code>half</code>元素，数据整体长度为256000个<code>half</code>元素。数据平均分配到8个核上处理，每个核计算32000个元素；每个核内共切分成10个主块，不涉及尾块和尾核处理。</p><h2 id="Tiling实现">Tiling实现<a class="header-anchor" href="#Tiling实现">​</a></h2><p>基于本节的切分策略，Tiling需要定义如下参数：</p><ul><li>blockLength：每个核处理的数据长度，单位为元素。</li><li>tileNum：每个核需要计算的主块个数。</li></ul><p>据此定义<code>MainTileOnlyTiling</code>结构体，代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">struct</span><span class="w"> </span><span class="nc">MainTileOnlyTiling</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockLength</span><span class="p">;</span><span class="w"> </span><span class="c1">// 每个核处理的元素数量</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">tileNum</span><span class="p">;</span><span class="w">     </span><span class="c1">// 主块数量</span>
<span class="p">};</span>
</code></pre></div><p>接下来完成Tiling参数的计算。涉及的主要变量包括：逻辑核数<code>numBlocks</code>、一个DataBlock的字节数<code>dataBlockSize</code>、一个<code>half</code>元素的字节数<code>halfSize</code>、一个DataBlock包含的<code>half</code>元素数量<code>alignNum</code>、一个主块包含的<code>half</code>元素数量<code>mainTileLength</code>。步骤如下：</p><ol><li><p>根据<code>dataBlockSize</code>和<code>halfSize</code>计算<code>alignNum</code>，本样例中<code>alignNum</code>为16。<code>totalLength</code>为输入数据的元素总数，将其按<code>alignNum</code>向上对齐后得到对齐后的元素总数<code>totalLengthAligned</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dataBlockSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">halfSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">alignNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">dataBlockSize</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">halfSize</span><span class="p">;</span>

<span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLengthAligned</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AlignUp</span><span class="p">(</span><span class="n">totalLength</span><span class="p">,</span><span class="w"> </span><span class="n">alignNum</span><span class="p">);</span>
</code></pre></div></li><li><p>用<code>totalLengthAligned</code>除以<code>numBlocks * mainTileLength</code>得到每个核均分到的主块数量<code>mainTileNum</code>，取余得到主块均分后的剩余元素数量<code>mainTileRemainder</code>；再将<code>mainTileNum</code>乘以<code>mainTileLength</code>得到每个核已分配的元素数量<code>baseLength</code>，<code>baseTileNum</code>直接取<code>mainTileNum</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">numBlocks</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">mainTileLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3200</span><span class="p">;</span>

<span class="kt">uint32_t</span><span class="w"> </span><span class="n">mainTileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalLengthAligned</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="p">(</span><span class="n">numBlocks</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">mainTileLength</span><span class="p">);</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">mainTileRemainder</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalLengthAligned</span><span class="w"> </span><span class="o">%</span><span class="w"> </span><span class="p">(</span><span class="n">numBlocks</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">mainTileLength</span><span class="p">);</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">baseLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">mainTileNum</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">mainTileLength</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">baseTileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">mainTileNum</span><span class="p">;</span>
</code></pre></div></li><li><p>当<code>mainTileRemainder</code>为0时，表示所有数据都能按主块均匀分配到各核，此时使用<code>MainTileOnlyTiling</code>结构体传递Tiling切分信息。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">if</span><span class="w"> </span><span class="p">(</span><span class="n">mainTileRemainder</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">0U</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">MainTileOnlyTiling</span><span class="w"> </span><span class="n">tiling</span><span class="p">{</span><span class="n">baseLength</span><span class="p">,</span><span class="w"> </span><span class="n">baseTileNum</span><span class="p">};</span>
<span class="w">    </span><span class="n">add_custom</span><span class="o">&lt;</span><span class="n">MainTileOnlyTiling</span><span class="o">&gt;&lt;&lt;&lt;</span><span class="n">numBlocks</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">xDevice</span><span class="p">,</span><span class="w"> </span><span class="n">yDevice</span><span class="p">,</span><span class="w"> </span><span class="n">zDevice</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
<span class="w">    </span><span class="k">return</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></li></ol><h2 id="算子类实现">算子类实现<a class="header-anchor" href="#算子类实现">​</a></h2><p>核函数（Kernel）侧算子使用C API，通过GM指针和显式UB数组管理数据。内存管理和同步管理通过显式地址空间与C API同步接口完成，本节重点说明各核GM地址的计算以及主块数据的循环处理流程。</p><ul><li><p>核函数（Kernel）入口接收Host侧传入的Tiling结构体，并依次调用算子类的<code>Init</code>与<code>Process</code>函数完成初始化与计算。主块均分场景中，传入的结构体类型为<code>MainTileOnlyTiling</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">TilingData</span><span class="o">&gt;</span>
<span class="n">__vector__</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">TilingData</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_init</span><span class="p">();</span>
<span class="w">    </span><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
<span class="w">    </span><span class="n">op</span><span class="p">.</span><span class="n">Process</span><span class="p">();</span>
<span class="w">    </span><span class="n">asc_sync</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div></li><li><p>由于数据被分配到多个核上处理，每个核访问的Global Memory地址范围各不相同。<code>Init</code>函数通过<code>tiling.blockLength</code>获取每个核处理的元素数量，并结合<code>block_idx</code>计算当前核所处理数据在Global Memory上的起始偏移<code>offset</code>，随后将偏移与长度传入<code>InitGm</code>完成GM地址设置；同时将<code>tiling.tileNum</code>保存到成员变量，供<code>Process</code>函数使用。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Init</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">                            </span><span class="n">MainTileOnlyTiling</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">blockLength</span><span class="p">;</span>
<span class="w">    </span><span class="n">InitGm</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">tileNum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">tiling</span><span class="p">.</span><span class="n">tileNum</span><span class="p">;</span>
<span class="w">    </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">lastTileLength</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0U</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></li><li><p><code>InitGm</code>函数通过GM指针赋值为输入<code>xGm</code>、<code>yGm</code>和输出<code>zGm</code>设置Global Memory地址。以输入x为例，<code>(__gm__ half*)x + offset</code>即为当前核处理数据在Global Memory上的起始地址，<code>length</code>为该核处理的元素数量。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">InitGm</span><span class="p">(</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">offset</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">length</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">xGm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">;</span>
<span class="w">    </span><span class="n">yGm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">;</span>
<span class="w">    </span><span class="n">zGm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="n">half</span><span class="o">*</span><span class="p">)</span><span class="n">z</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">offset</span><span class="p">;</span>
<span class="p">}</span>
</code></pre></div></li><li><p><code>Process</code>函数基于成员变量<code>tileNum</code>循环处理主块数据。<code>xLocal</code>、<code>yLocal</code>、<code>zLocal</code>为显式分配的UB数组。循环次数采用<code>tileNum + (lastTileLength &gt; 0U ? 1U : 0U)</code>的通用形式计算，主块均分场景下<code>lastTileLength</code>为0，循环次数即等于<code>tileNum</code>。每轮循环以<code>mainTileLength</code>作为当前主块的元素数量，通过<code>loopIdx * mainTileLength</code>计算核内偏移<code>startElement</code>，依次完成输入搬入、Add计算和输出搬出。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Process</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">xLocal</span><span class="p">[</span><span class="n">mainTileLength</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">yLocal</span><span class="p">[</span><span class="n">mainTileLength</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">zLocal</span><span class="p">[</span><span class="n">mainTileLength</span><span class="p">];</span>

<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">totalLoop</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">tileNum</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="p">(</span><span class="k">this</span><span class="o">-&gt;</span><span class="n">lastTileLength</span><span class="w"> </span><span class="o">&gt;</span><span class="w"> </span><span class="mi">0U</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="mi">1U</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="mi">0U</span><span class="p">);</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">loopIdx</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">loopIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">totalLoop</span><span class="p">;</span><span class="w"> </span><span class="n">loopIdx</span><span class="o">++</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">curLen</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="n">loopIdx</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">tileNum</span><span class="p">)</span><span class="w"> </span><span class="o">?</span><span class="w"> </span><span class="n">mainTileLength</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">lastTileLength</span><span class="p">;</span>
<span class="w">        </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">startElement</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">loopIdx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">mainTileLength</span><span class="p">;</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xGm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">startElement</span><span class="p">,</span><span class="w"> </span><span class="n">curLen</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">startElement</span><span class="p">,</span><span class="w"> </span><span class="n">curLen</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">AddVF</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">curLen</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_sync_notify</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_sync_wait</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">EVENT_ID0</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">zGm</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">startElement</span><span class="p">,</span><span class="w"> </span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">curLen</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">));</span>
<span class="w">        </span><span class="c1">// 下一轮复用同一组UB前，等待本轮读写全部结束。</span>
<span class="w">        </span><span class="n">asc_sync</span><span class="p">();</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></li></ul><p>上述代码片段属于同一个<code>KernelAdd</code>类，类中需要声明<code>__gm__ half *xGm, *yGm, *zGm;</code>、<code>uint32_t tileNum, lastTileLength;</code>和<code>static constexpr uint32_t mainTileLength = 3200;</code>。包含头文件<code>&quot;c_api/asc_simd.h&quot;</code>，核函数入口前先定义算子类。示例串行复用UB，跨块流水重叠参见<a href="../double_buffer_scenario.html">DoubleBuffer场景</a>。Host按16个half向上对齐后，须为对齐部分预留GM空间。</p><h2 id="Reg矢量函数实现">Reg矢量函数实现<a class="header-anchor" href="#Reg矢量函数实现">​</a></h2><p>上述计算通过asc_vf_call调用以下矢量函数。实际源文件中将该定义放在调用位置之前；输入UB数组须按完整VL（256字节）向上对齐预留，搬运仍只处理实际数据长度。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;c_api/asc_simd.h&quot;</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__simd_vf__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">AddVF</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">T</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">remain</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">count</span><span class="p">;</span>
<span class="w">    </span><span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">count</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">+=</span><span class="w"> </span><span class="mi">256</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">T</span><span class="p">))</span><span class="w"> </span><span class="p">{</span>
<span class="w">        </span><span class="n">vector_bool</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="w">        </span><span class="k">if</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="p">(</span><span class="k">sizeof</span><span class="p">(</span><span class="n">T</span><span class="p">)</span><span class="w"> </span><span class="o">==</span><span class="w"> </span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b16</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="w">        </span><span class="p">}</span><span class="w"> </span><span class="k">else</span><span class="w"> </span><span class="p">{</span>
<span class="w">            </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_update_mask_b32</span><span class="p">(</span><span class="n">remain</span><span class="p">);</span>
<span class="w">        </span><span class="p">}</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">a</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="p">);</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">b</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_loadalign</span><span class="p">(</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="p">);</span>
<span class="w">        </span><span class="k">auto</span><span class="w"> </span><span class="n">result</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_add</span><span class="p">(</span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">        </span><span class="n">asc_storealign</span><span class="p">(</span><span class="n">dst</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">i</span><span class="p">,</span><span class="w"> </span><span class="n">result</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const r=n(e,[["render",t]]);export{m as __pageData,r as default};
